import AppKit
import os

final class CommandXManager {
    private let logger = Logger(subsystem: "com.riyazjpersonalteam.WinManager", category: "CommandX")
    private var fileIsCut = false
    private var cutChangeCount: Int = -1

    func handleKeyEvent(_ event: CGEvent, type: CGEventType) -> CGEvent? {
        guard type == .keyDown, UserDefaults.standard.bool(forKey: "enableCommandX") else { return event }

        // Ignore synthetic events generated by WinManager
        if event.getIntegerValueField(.eventSourceUserData) == EventTapController.syntheticEventTag {
            return event
        }

        let keyCode = event.getIntegerValueField(.keyboardEventKeycode)
        let flags = event.flags

        guard let frontApp = NSWorkspace.shared.frontmostApplication,
              frontApp.bundleIdentifier == "com.apple.finder" else {
            // If active app is not Finder, reset any cut state
            if fileIsCut { resetCutState() }
            return event
        }

        // Cancel on Escape (key code 53)
        if keyCode == 53 {
            resetCutState()
            return event
        }

        // Normal ⌘C (key code 8) overrides and cancels cut
        if keyCode == 8, flags.contains(.maskCommand) {
            resetCutState()
            return event
        }

        // ⌘X (Keycode 7) in Finder
        if keyCode == 7, flags.contains(.maskCommand) {
            logger.info("Cmd+X intercepted in Finder. Converting to Copy (Cmd+C)...")
            postSyntheticKey(keyCode: 8, flags: .maskCommand)

            // Mark file as cut and observe pasteboard state
            fileIsCut = true
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { [weak self] in
                self?.cutChangeCount = NSPasteboard.general.changeCount
            }

            return nil // Swallow original ⌘X to prevent macOS error beep
        }

        // ⌘V (Keycode 9) in Finder
        if keyCode == 9, flags.contains(.maskCommand) {
            if fileIsCut {
                // Verify that the pasteboard actually has files before transforming
                let pasteboard = NSPasteboard.general
                let hasFiles = pasteboard.canReadItem(withDataConformingToTypes: [NSPasteboard.PasteboardType.fileURL.rawValue])

                if hasFiles {
                    logger.info("Cmd+V intercepted in Finder with active cut. Executing Move (Cmd+Opt+V)...")
                    resetCutState()
                    postSyntheticKey(keyCode: 9, flags: [.maskCommand, .maskAlternate])
                    return nil // Swallow original ⌘V
                } else {
                    resetCutState()
                }
            }
        }

        return event
    }

    func resetCutState() {
        if fileIsCut {
            logger.info("Resetting Finder cut state.")
            fileIsCut = false
            cutChangeCount = -1
        }
    }

    private func postSyntheticKey(keyCode: CGKeyCode, flags: CGEventFlags) {
        guard let source = CGEventSource(stateID: .combinedSessionState) else { return }

        if let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true) {
            keyDown.flags = flags
            keyDown.setIntegerValueField(.eventSourceUserData, value: EventTapController.syntheticEventTag)
            keyDown.post(tap: .cgSessionEventTap)
        }

        if let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false) {
            keyUp.flags = flags
            keyUp.setIntegerValueField(.eventSourceUserData, value: EventTapController.syntheticEventTag)
            keyUp.post(tap: .cgSessionEventTap)
        }
    }
}

